module radix2_div (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output reg [15:0] result
);

localparam MAX_ITER = 8;

reg [15:0] div_reg;
reg [15:0] rem_reg;
reg [3:0] cnt;
reg [3:0] start_cnt;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        div_reg <= 0;
        rem_reg <= 0;
        cnt <= 0;
        start_cnt <= 0;
        res_valid <= 0;
    end else if (opn_valid && !res_valid) begin
        div_reg <= {dividend[7], dividend};
        rem_reg <= {sign ? ~dividend : dividend, 8'b0};
        rem_reg <= rem_reg + (sign ? ~divisor : divisor) + 1;
        cnt <= 0;
        start_cnt <= 1;
    end else if (start_cnt) begin
        if (cnt == MAX_ITER) begin
            cnt <= 0;
            start_cnt <= 0;
            result <= {rem_reg, div_reg};
            res_valid <= 1;
        end else begin
            cnt <= cnt + 1;
            if (rem_reg >= {sign ? ~divisor : divisor}) begin
                rem_reg <= rem_reg - {sign ? ~divisor : divisor};
                div_reg <= div_reg + 1;
            end
            rem_reg <= rem_reg << 1;
            div_reg <= div_reg << 1;
        end
    end else begin
        res_valid <= 0;
    end
end

endmodule
